public final class PryanikPlugin extends JavaPlugin implements Listener {
    private Database db;
    private GameModes gameModes;
    private GameStateManager gameStateManager;
    private AuthSessionManager authSessionManager;
    private AdminHttpApi adminHttpApi;
    public GameModes gameModes(){return gameModes;}
    public GameStateManager gameStateManager(){return gameStateManager;}
    public long authRememberDuration(UUID id){return authSessionManager==null?86_400_000L:authSessionManager.duration(id);}
    public void setAuthRememberDuration(Player player,long duration){if(authSessionManager!=null)authSessionManager.setDuration(player,duration);}
    public void runPortalPlayerCommand(Player player,String command){if(player==null||!player.isOnline())return;player.setPortalCooldown(Math.max(player.getPortalCooldown(),1200));switch(command){case "mode"->{if(gameModes.isLobby(player.getWorld()))new GameModeCommand(this).openModes(player);else gameModes.goHub(player,()->new GameModeCommand(this).openModes(player));}case "lobby"->gameModes.goHub(player);case "kit_start"->Bukkit.dispatchCommand(player,"kit_start");case "home"->Bukkit.dispatchCommand(player,"home");case "chome"->Bukkit.dispatchCommand(player,"chome");case "rtp"->Bukkit.dispatchCommand(player,"rtp");default->player.sendMessage("§cДля этого портала команда не настроена.");}}
    public String clanScope(Player p){String id=gameModes==null?null:gameModes.instanceOf(p.getWorld().getName());return id==null?(gameModes!=null&&gameModes.isLobby(p.getWorld())?"lobby":"legacy"):gameModes.isSpawnWorld(p.getWorld())?"legacy":id;}
    private final Set<UUID> auth=new HashSet<>(),afk=new HashSet<>(),van=new HashSet<>();
    private final Map<UUID,Long> protection=new HashMap<>(); private final Set<UUID> exemptDamage=new HashSet<>();
    private final Map<UUID,org.bukkit.scheduler.BukkitTask> authTimeouts=new HashMap<>();
    private final Map<UUID,UUID> requests=new HashMap<>(), replies=new HashMap<>();
    private final Map<UUID,Long> combatUntil=new HashMap<>();
    private final Map<UUID,UUID> combatOpponents=new HashMap<>();
    private final Map<UUID,org.bukkit.boss.BossBar> combatBars=new HashMap<>();
    public Database db(){return db;} public boolean authed(UUID id){return auth.contains(id);} public boolean afk(UUID id){return afk.contains(id);} public boolean van(UUID id){return van.contains(id);}
    public void authenticate(Player p){UUID id=p.getUniqueId();auth.add(id);exemptDamage.remove(id);protection.remove(id);org.bukkit.scheduler.BukkitTask timeout=authTimeouts.remove(id);if(timeout!=null)timeout.cancel();restore(p);if(gameModes!=null&&gameModes.isLobby(p.getWorld()))Bukkit.getScheduler().runTaskLater(this,()->{if(p.isOnline()&&gameModes.isLobby(p.getWorld()))gameModes.giveLobbyCompass(p);},2L);p.setPlayerListName(p.getName());p.sendMessage("§aВход выполнен.");updateRank(p);if(gameModes!=null)Bukkit.getScheduler().runTaskLater(this,()->{if(p.isOnline()&&authed(id))gameModes.syncVisibility();},2L);}
    public void updateRank(Player p){try{Rank r=db.rank(p.getUniqueId());Scoreboard b=Bukkit.getScoreboardManager().getMainScoreboard();String key=r.name();Team t=b.getTeam(key);if(t==null)t=b.registerNewTeam(key);t.setPrefix(r.prefix()+" §f");for(Team other:b.getTeams())if(other!=t)other.removeEntry(p.getName());t.addEntry(p.getName());Objective health=b.getObjective("pp_health");if(health==null)health=b.registerNewObjective("pp_health","health","§c❤");health.setDisplaySlot(DisplaySlot.BELOW_NAME);p.setScoreboard(b);p.setPlayerListName(r.prefix()+" §f"+p.getName());}catch(Exception ignored){}}
    public void refreshLobbyPlayer(Player p){if(gameModes!=null&&gameModes.isLobby(p.getWorld())){p.setGameMode(GameMode.ADVENTURE);p.setInvulnerable(true);p.setFallDistance(0);p.setFireTicks(0);}else p.setInvulnerable(afk(p.getUniqueId())||van(p.getUniqueId()));} public void hide(Player p){p.setInvulnerable(true);p.setSilent(true);p.setCollidable(false);p.setInvisible(true);p.setSleepingIgnored(true);for(Player v:Bukkit.getOnlinePlayers())if(v!=p)v.hidePlayer(this,p);}
    public void restore(Player p){boolean hidden=afk(p.getUniqueId())||van(p.getUniqueId());p.setInvulnerable(hidden||(gameModes!=null&&gameModes.isLobby(p.getWorld())));p.setSilent(hidden);p.setCollidable(!hidden);p.setInvisible(hidden);for(Player v:Bukkit.getOnlinePlayers())if(v!=p){if(hidden||!authed(v.getUniqueId()))v.hidePlayer(this,p);else v.showPlayer(this,p);}if(hidden)p.setPlayerListName("§0");}
    public boolean toggleAfk(Player p){if(inCombat(p.getUniqueId())){p.sendMessage("§cНельзя включать AFK в бою.");return afk(p.getUniqueId());}if(afk(p.getUniqueId()))afk.remove(p.getUniqueId());else afk.add(p.getUniqueId());restore(p);return afk(p.getUniqueId());}
    public boolean toggleVan(Player p,boolean enabled){if(enabled)van.add(p.getUniqueId());else van.remove(p.getUniqueId());restore(p);return enabled;}
    public long combatRemaining(UUID id){return Math.max(0L,combatUntil.getOrDefault(id,0L)-System.currentTimeMillis());}
    public boolean inCombat(UUID id){return combatRemaining(id)>0;}
    public void clearCombat(UUID id){combatUntil.remove(id);UUID opponent=combatOpponents.remove(id);if(opponent!=null&&id.equals(combatOpponents.get(opponent)))combatOpponents.remove(opponent);org.bukkit.boss.BossBar bar=combatBars.remove(id);if(bar!=null)bar.removeAll();}
    private void tagCombatant(Player p){if(p==null)return;UUID id=p.getUniqueId();combatUntil.put(id,System.currentTimeMillis()+30_000L);org.bukkit.boss.BossBar bar=combatBars.computeIfAbsent(id,k->Bukkit.createBossBar("§cPvP: 30 сек",org.bukkit.boss.BarColor.RED,org.bukkit.boss.BarStyle.SOLID));bar.setTitle("§cPvP: 30 сек");bar.setProgress(1.0);bar.addPlayer(p);bar.setVisible(true);}
    public boolean pvpEnabled(World world){if(world==null||gameModes==null||gameModes.isLobby(world)||gameModes.isSpawnWorld(world))return false;String instance=gameModes.instanceOf(world.getName());if(instance==null)return world.getPVP();try{return db.pvpEnabled(instance)&&world.getPVP();}catch(Exception ex){return false;}}
    public void setWorldPvpFlag(World world,boolean enabled){if(world!=null)world.setPVP(enabled);}
    public boolean isCombatant(UUID id){return combatUntil.containsKey(id);}
    private void tagCombat(Player a,Player b){tagCombatant(a);tagCombatant(b);UUID aid=a.getUniqueId(),bid=b.getUniqueId();UUID oldA=combatOpponents.put(aid,bid),oldB=combatOpponents.put(bid,aid);if(oldA!=null&&!oldA.equals(bid)&&aid.equals(combatOpponents.get(oldA)))combatOpponents.remove(oldA);if(oldB!=null&&!oldB.equals(aid)&&bid.equals(combatOpponents.get(oldB)))combatOpponents.remove(oldB);}
    private void updateCombatBars(){long now=System.currentTimeMillis();for(UUID id:new ArrayList<>(combatUntil.keySet())){Player p=Bukkit.getPlayer(id);long remaining=combatUntil.getOrDefault(id,0L)-now;org.bukkit.boss.BossBar bar=combatBars.get(id);if(remaining<=0||p==null||!p.isOnline()){combatUntil.remove(id);if(bar!=null){bar.removeAll();combatBars.remove(id);}continue;}if(bar!=null){bar.setTitle("§cPvP: "+((remaining+999)/1000)+" сек");bar.setProgress(Math.max(0.0,Math.min(1.0,remaining/30_000.0)));}}}
    private void startCombatBarTask(){Bukkit.getScheduler().runTaskTimer(this,this::updateCombatBars,1L,5L);}
    private boolean blockCombatEscape(Player p,String command){if(!inCombat(p.getUniqueId()))return false;String root=command.toLowerCase(Locale.ROOT);if(root.equals("kit_start")||root.equals("pvp"))return false;if(Set.of("lobby","home","chome","clan","fly","world","tpa","tpaap","tapde","spawn","warp","back","rtp","mode").contains(root)){p.sendMessage("§cНельзя использовать /"+root+" в бою. Осталось "+((combatRemaining(p.getUniqueId())+999)/1000)+" сек.");return true;}return false;}
    public UUID takeRequest(UUID id){return requests.remove(id);}public void putRequest(UUID target,UUID sender){requests.put(target,sender);}public UUID replyTarget(UUID id){return replies.get(id);}public void setReply(UUID a,UUID b){replies.put(a,b);}
    @Override public void onEnable(){saveDefaultConfig();db=new Database(this);for(Player online:Bukkit.getOnlinePlayers())try{db.recordPlayerOnline(online.getUniqueId(),online.getName(),true);}catch(Exception ex){getLogger().warning("Could not restore online status: "+ex.getMessage());}Bukkit.getScheduler().runTaskTimer(this,this::checkWebsiteBans,200L,200L);Bukkit.getScheduler().runTaskTimer(this,this::processWebsiteRankRequests,100L,100L);getServer().getPluginManager().registerEvents(this,this);authSessionManager=new AuthSessionManager(this);getServer().getPluginManager().registerEvents(authSessionManager,this);gameModes=new GameModes(this);getServer().getPluginManager().registerEvents(gameModes,this);startCombatBarTask();gameStateManager=new GameStateManager(this);getServer().getPluginManager().registerEvents(gameStateManager,this);setupHealthDisplay();loadManagedWorlds();gameModes.refreshIndex();gameModes.configureLoadedSpawnWorlds();gameModes.ensureLobby();Bukkit.getScheduler().runTask(this,gameModes::configureAllLobbyPlayers);if(gameModes.lobby()==null){getLogger().severe("Required lobby world could not be loaded; disabling PryanikPlugin to prevent unsafe joins.");getServer().getPluginManager().disablePlugin(this);return;}adminHttpApi=new AdminHttpApi(this);adminHttpApi.start();if(getServer().getPluginManager().getPlugin("Multiverse-Core")!=null)getLogger().info("Multiverse-Core found; worlds managed by Bukkit/MV are available through /world and /mv.");else getLogger().info("Multiverse-Core not found; built-in Bukkit world management remains available.");for(String name:List.of("auth","reg","register","l","login","setrank","fly","van","afk","tpa","tpaap","tapde","tpablock","msg","r","privat","clan","home","chome","chprivat","chprivatdelete","clanset","world","report","code","mode","lobby","kit_start","ppadmin","gm","pvp","portal","villager","rtp")){   var c=getCommand(name);if(c!=null){if(name.equals("portal")){PortalCommand portalCommand=new PortalCommand(this);c.setExecutor(portalCommand);getServer().getPluginManager().registerEvents(portalCommand,this);}else if(name.equals("home")||name.equals("chome")){var homeCommand=new com.example.pryanik.commands.HomeCommand(this,name);c.setExecutor(homeCommand);getServer().getPluginManager().registerEvents(homeCommand,this);}else if(name.equals("ppadmin")){var adminCommand=new com.example.pryanik.commands.PPAdminCommand(this);c.setExecutor(adminCommand);getServer().getPluginManager().registerEvents(adminCommand,this);}else if(name.equals("lobby")){ c.setExecutor((sender,cmd,label,args)->{if(!(sender instanceof Player player)){sender.sendMessage("Только игрок.");return true;}if(!authed(player.getUniqueId())){player.sendMessage("§cСначала войдите.");return true;}gameModes.goHub(player);return true;});}else if(name.equals("kit_start")){c.setExecutor(new com.example.pryanik.commands.StarterKitCommand(this));}else if(name.equals("gm")){c.setExecutor(new com.example.pryanik.commands.GameModeToggleCommand(this));}else if(name.equals("pvp")){c.setExecutor(new com.example.pryanik.commands.PvpToggleCommand(this));}else if(name.equals("portal")){var command=new com.example.pryanik.commands.PortalCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("villager")){var command=new com.example.pryanik.commands.VillagerCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("rtp")){c.setExecutor(new com.example.pryanik.commands.RtpCommand(this));}else if(name.equals("auth")){var command=new AuthSessionCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("privat")){var command=new com.example.pryanik.commands.PrivatCommand(this);c.setExecutor(command);c.setTabCompleter(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("home")||name.equals("chome")){var command=new com.example.pryanik.commands.HomeCommand(this,name);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("chprivat")){var command=new com.example.pryanik.commands.ClanPrivateCommand(this,false);c.setExecutor(command);}else if(name.equals("chprivatdelete")){var command=new com.example.pryanik.commands.ClanPrivateCommand(this,true);c.setExecutor(command);}else if(name.equals("mode")){ var command=new GameModeCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("code")){ c.setExecutor(new CodeCommand(this));}else if(name.equals("report")){var command=new ReportCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("world")){ var command=new WorldCommand(this);c.setExecutor(command);c.setTabCompleter(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("clanset")){ c.setExecutor(new ClanSetCommand(this));}else if(name.equals("privat")){ var command=new PrivatCommand(this);c.setExecutor(command);c.setTabCompleter(command);}else if(name.equals("clan")){var command=new ClanCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("chprivat")||name.equals("chprivatdelete")){c.setExecutor(new ClanPrivateCommand(this,name.equals("chprivatdelete")));}else{var command=new AuthCommands(this,name);c.setExecutor(command);c.setTabCompleter(command);}}}}
    public int modeCount(String mode){return gameModes.count(mode);} public int modeCapacity(String mode){return gameModes.capacity(mode);} public int instanceOnline(String id){return gameModes.online(id);} public String playerSavedWorld(UUID id){try{String[] position=db.position(id);return position==null?null:position[0];}catch(Exception e){return null;}} public String[] savedPosition(UUID id){try{return db.position(id);}catch(Exception e){return null;}} public String instanceOf(String world){return gameModes.instanceOf(world);} public World lobby(){return gameModes.lobby();} public void enterInstance(Player p,String mode,int no){gameModes.enter(p,mode,no);} public void banHardcore(UUID id,String instance){gameModes.banHardcore(id,instance);}
     private void loadExistingManagedWorld(String name,World.Environment env){if(Bukkit.getWorld(name)!=null)return;java.io.File folder=new java.io.File(Bukkit.getWorldContainer(),name);if(!folder.exists()){getLogger().warning("Managed world folder missing; not creating a replacement: "+name);return;}if(!new java.io.File(folder,"level.dat").isFile()){getLogger().severe("Managed world folder has no level.dat; refusing to overwrite: "+name);return;}World loaded=Bukkit.createWorld(new WorldCreator(name).environment(env));if(loaded==null)getLogger().severe("Could not load existing managed world: "+name);else getLogger().info("Loaded existing managed world: "+name);} private void setupHealthDisplay(){Scoreboard board=Bukkit.getScoreboardManager().getMainScoreboard();Objective objective=board.getObjective("pp_health");if(objective==null)objective=board.registerNewObjective("pp_health","health","§c❤");objective.setDisplaySlot(DisplaySlot.BELOW_NAME);for(Player player:Bukkit.getOnlinePlayers())player.setScoreboard(board);} private void loadManagedWorlds(){try{for(String[] instance:db.gameInstances()){String base=instance[2];String[] names={base,base+"_nether",base+"_the_end",base+"_spawn"};World.Environment[] envs={World.Environment.NORMAL,World.Environment.NETHER,World.Environment.THE_END,World.Environment.NORMAL};for(int i=0;i<names.length;i++)loadExistingManagedWorld(names[i],envs[i]);}for(String[] set:db.managedWorldSets()){String[] names=set.length>4&&!set[4].isBlank()?new String[]{set[1],set[2],set[3],set[4]}:new String[]{set[1],set[2],set[3]};World.Environment[] envs=names.length==4?new World.Environment[]{World.Environment.NORMAL,World.Environment.NETHER,World.Environment.THE_END,World.Environment.NORMAL}:new World.Environment[]{World.Environment.NORMAL,World.Environment.NETHER,World.Environment.THE_END};for(int i=0;i<names.length;i++)loadExistingManagedWorld(names[i],envs[i]);}for(String[] entry:db.managedWorlds()){if(Bukkit.getWorld(entry[0])!=null)continue;World.Environment env=switch(entry[1].toUpperCase(Locale.ROOT)){case "NETHER"->World.Environment.NETHER;case "THE_END"->World.Environment.THE_END;default->World.Environment.NORMAL;};World loaded=Bukkit.createWorld(new WorldCreator(entry[0]).environment(env));if(loaded==null)getLogger().warning("Could not load plugin-managed world: "+entry[0]);else getLogger().info("Loaded plugin-managed world: "+entry[0]);}}catch(Exception e){getLogger().severe("Could not load managed worlds from PostgreSQL: "+e.getMessage());}}
    @Override public void onDisable(){if(adminHttpApi!=null)adminHttpApi.stop();if(db!=null){for(Player p:Bukkit.getOnlinePlayers())try{db.recordPlayerOnline(p.getUniqueId(),p.getName(),false);}catch(Exception ex){getLogger().warning("Could not clear online status: "+ex.getMessage());}db.close();}}
    private void processWebsiteRankRequests(){try{for(String[] row:db.pendingWebsiteRankRequests()){long requestId=Long.parseLong(row[0]);UUID target=UUID.fromString(row[1]);UUID actor=UUID.fromString(row[4]);try{Rank requested=Rank.parse(row[3]);if(db.rank(actor)==Rank.CSRV&&db.rank(target)!=Rank.CSRV){String name=db.nickname(target);db.setRank(target,name,requested);Player online=Bukkit.getPlayer(target);if(online!=null)updateRank(online);}}finally{db.deleteWebsiteRankRequest(requestId);}}}catch(Exception ex){getLogger().warning("Website rank request processing failed: "+ex.getMessage());}}
    private void checkWebsiteBans(){for(Player online:Bukkit.getOnlinePlayers()){UUID id=online.getUniqueId();try{String reason=db.websiteBanReason(id);if(reason!=null)Bukkit.getScheduler().runTask(this,()->{Player current=Bukkit.getPlayer(id);if(current!=null&&current.isOnline())current.kickPlayer("§cДоступ к серверу закрыт. Причина: §f"+reason);});}catch(Exception ex){getLogger().warning("Website ban polling failed: "+ex.getMessage());return;}}}
    private void startAuthTimeout(Player player){UUID id=player.getUniqueId();org.bukkit.scheduler.BukkitTask old=authTimeouts.remove(id);if(old!=null)old.cancel();boolean registered;try{registered=db.exists(id);}catch(Exception ex){getLogger().warning("Could not check registration state for "+player.getName()+": "+ex.getMessage());player.kickPlayer("§cНе удалось проверить аккаунт. Попробуйте позже.");return;}String prompt=registered?"§eВы уже зарегистрированы. Войдите: §f/l [пароль]":"§eЗарегистрируйтесь: §f/reg [пароль]";player.sendMessage(prompt);final int[] seconds={0};org.bukkit.scheduler.BukkitTask task=Bukkit.getScheduler().runTaskTimer(this,()->{if(!player.isOnline()||authed(id)){org.bukkit.scheduler.BukkitTask taskRef=authTimeouts.remove(id);if(taskRef!=null)taskRef.cancel();return;}seconds[0]+=5;if(seconds[0]>=60){authTimeouts.remove(id);player.kickPlayer("§cВремя на авторизацию истекло.");return;}player.sendMessage(prompt);},100L,100L);authTimeouts.put(id,task);} @EventHandler(priority=EventPriority.LOWEST) public void websiteBanCheck(PlayerJoinEvent e){try{String reason=db.websiteBanReason(e.getPlayer().getUniqueId());if(reason!=null){e.getPlayer().kickPlayer("§cДоступ к серверу закрыт. Причина: §f"+reason);e.setJoinMessage(null);return;}db.recordPlayerOnline(e.getPlayer().getUniqueId(),e.getPlayer().getName(),true);}catch(Exception ex){getLogger().warning("Website ban check failed: "+ex.getMessage());}} @EventHandler public void onJoinScoreboard(PlayerJoinEvent e){e.getPlayer().setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());} @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void blockCombatTeleport(PlayerTeleportEvent e){if(inCombat(e.getPlayer().getUniqueId())&&e.getCause()!=PlayerTeleportEvent.TeleportCause.COMMAND&&e.getCause()!=PlayerTeleportEvent.TeleportCause.UNKNOWN){e.setCancelled(true);e.getPlayer().sendMessage("§cНельзя телепортироваться во время боя. Осталось "+((combatRemaining(e.getPlayer().getUniqueId())+999)/1000)+" сек.");}} @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void allowInstanceTravel(PlayerTeleportEvent e){if(gameModes!=null&&!gameModes.mayTeleport(e.getPlayer(),e.getTo())){e.setCancelled(true);e.getPlayer().sendMessage("§cВ этот хардкорный гриф вам нельзя возвращаться после смерти.");}} @EventHandler(priority=EventPriority.HIGHEST) public void linkedPortal(PlayerPortalEvent e){if(e.getCause()!=PlayerTeleportEvent.TeleportCause.NETHER_PORTAL&&e.getCause()!=PlayerTeleportEvent.TeleportCause.END_PORTAL)return;World from=e.getFrom().getWorld();if(from==null)return;try{String[] set=db.worldSetFor(from.getName());if(set==null)return;String targetName;if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL)targetName=from.getEnvironment()==World.Environment.NETHER?set[1]:set[2];else targetName=from.getEnvironment()==World.Environment.THE_END?set[1]:from.getName().endsWith("_spawn")?set[1]:set[3];World target=Bukkit.getWorld(targetName);if(target==null){World.Environment env=targetName.equals(set[1])||set.length>4&&targetName.equals(set[4])?World.Environment.NORMAL:targetName.equals(set[2])?World.Environment.NETHER:World.Environment.THE_END;target=Bukkit.createWorld(new WorldCreator(targetName).environment(env));}if(target==null){e.setCancelled(true);e.getPlayer().sendMessage("§cНе удалось загрузить измерение "+targetName);return;}Location original=e.getTo()==null?target.getSpawnLocation():e.getTo();double x=original.getX(),z=original.getZ();if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL&&from.getEnvironment()!=World.Environment.NETHER){x/=8.0;z/=8.0;}else if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL){x*=8.0;z*=8.0;}int y=Math.max(target.getMinHeight()+1,Math.min(target.getMaxHeight()-2,original.getBlockY()));e.setTo(new Location(target,x,y,z,original.getYaw(),original.getPitch()));}catch(Exception ex){getLogger().warning("Linked portal routing failed: "+ex.getMessage());}} @EventHandler public void join(PlayerJoinEvent e){Player p=e.getPlayer();try{db.recordPlayerOnline(p.getUniqueId(),p.getName(),true);}catch(Exception ex){getLogger().warning("Could not update player online status: "+ex.getMessage());}auth.remove(p.getUniqueId());hide(p);startAuthTimeout(p);p.setPlayerListName("§0");for(Player v:Bukkit.getOnlinePlayers())if(v!=p&&!auth.contains(v.getUniqueId()))p.hidePlayer(this,v);e.setJoinMessage(null);String joinWorld=getConfig().getString("join-world","");if(!joinWorld.isBlank())getServer().getScheduler().runTask(this,()->{if(!p.isOnline())return;World target=Bukkit.getWorld(joinWorld);if(target==null){getLogger().warning("Configured join-world '"+joinWorld+"' is not loaded.");return;}p.teleport(target.getSpawnLocation());});}
    @EventHandler public void quit(PlayerQuitEvent e){try{db.recordPlayerOnline(e.getPlayer().getUniqueId(),e.getPlayer().getName(),false);}catch(Exception ex){getLogger().warning("Could not update player activity: "+ex.getMessage());}UUID id=e.getPlayer().getUniqueId();protection.remove(id);exemptDamage.remove(id);clearCombat(id);org.bukkit.scheduler.BukkitTask authTask=authTimeouts.remove(id);if(authTask!=null)authTask.cancel();auth.remove(id);afk.remove(id);van.remove(id);requests.remove(id);e.setQuitMessage(null);}
    @EventHandler public void move(PlayerMoveEvent e){Player p=e.getPlayer();UUID id=p.getUniqueId();if(!authed(id)||afk(id)){ if(e.getTo()!=null&&(e.getFrom().getX()!=e.getTo().getX()||e.getFrom().getZ()!=e.getTo().getZ()||e.getFrom().getY()!=e.getTo().getY())){e.setTo(e.getFrom());if(afk(id))p.sendMessage("§cВы в режиме AFK.");}}}
    @EventHandler(priority=EventPriority.HIGHEST) public void chat(AsyncPlayerChatEvent e){Player sender=e.getPlayer();if(!authed(sender.getUniqueId())){e.setCancelled(true);sender.sendMessage("§cСначала войдите.");return;}if(gameModes==null||gameModes.isLobby(sender.getWorld())){e.setCancelled(true);sender.sendMessage("§cВ лобби чат отключён.");return;}String instance=gameModes.instanceOf(sender.getWorld().getName());if(instance==null){e.setCancelled(true);sender.sendMessage("§cЧат доступен только внутри игрового грифа.");return;}for(Player recipient:new ArrayList<>(e.getRecipients()))if(!instance.equals(gameModes.instanceOf(recipient.getWorld().getName())))e.getRecipients().remove(recipient);try{String pref=db.rank(sender.getUniqueId()).prefix();e.setFormat(pref+" §f%s§7: §f%s");}catch(Exception ignored){}}
    private boolean isCreator(Player p){if(p.hasPermission("pryanik.creator"))return true;try{return db.rank(p.getUniqueId())==Rank.CSRV;}catch(Exception ex){return false;}}
    private boolean isProtectedGriefSpawn(World world){return gameModes!=null&&gameModes.isSpawnWorld(world);}
    private static final Set<String> LOBBY_ALLOWED_COMMANDS=Set.of("reg","l","auth","portal","gm","home","chome","ppadmin");
    private boolean lobbyCommandAllowed(String raw){String configured=getConfig().getString("admin-worlds.lobby.allowed-commands","").trim();if(raw.equals("reg")||raw.equals("l")||raw.equals("auth")||raw.equals("ppadmin")||raw.equals("home")||raw.equals("chome"))return true;if(configured.isEmpty())return LOBBY_ALLOWED_COMMANDS.contains(raw);if(configured.equalsIgnoreCase("all"))return true;if(configured.equalsIgnoreCase("none"))return Set.of("reg","l","auth","ppadmin","home","chome").contains(raw);return Set.of("reg","l","auth","ppadmin").contains(raw)||Arrays.stream(configured.split(",")).map(String::trim).anyMatch(raw::equals);}
    @EventHandler(priority=EventPriority.HIGHEST) public void lobbyCommands(PlayerCommandPreprocessEvent e){Player p=e.getPlayer();if(gameModes==null||!gameModes.isLobby(p.getWorld()))return;if(e.getMessage().equalsIgnoreCase("/portal")&&!authed(p.getUniqueId()))return;if(e.getMessage().matches("(?i)^/gm\\s+1$")&&authed(p.getUniqueId())){try{if(db.rank(p.getUniqueId()).atLeast(Rank.ADMIN))return;}catch(Exception ignored){}}if(e.getMessage().toLowerCase(Locale.ROOT).startsWith("/gm")&&!e.getMessage().matches("(?i)^/gm\\s+1$")&&authed(p.getUniqueId())){try{if(db.rank(p.getUniqueId()).atLeast(Rank.ADMIN))return;}catch(Exception ignored){}}String message=e.getMessage();String raw=message.length()>1?message.substring(1).split("\\s+",2)[0].toLowerCase(Locale.ROOT):"";if(!lobbyCommandAllowed(raw)){e.setCancelled(true);p.sendMessage("§cЭта команда не разрешена в лобби.");}}
     @EventHandler public void hideLobbyCommands(PlayerCommandSendEvent e){Player p=e.getPlayer();if(gameModes==null||!gameModes.isLobby(p.getWorld()))return;e.getCommands().removeIf(cmd->!LOBBY_ALLOWED_COMMANDS.contains(cmd.toLowerCase(Locale.ROOT)));}
    @EventHandler(priority=EventPriority.HIGHEST) public void advancement(org.bukkit.event.player.PlayerAdvancementDoneEvent e){if(gameModes!=null&&gameModes.isLobby(e.getPlayer().getWorld())){try{org.bukkit.advancement.AdvancementProgress progress=e.getPlayer().getAdvancementProgress(e.getAdvancement());for(String criteria:new ArrayList<>(progress.getAwardedCriteria()))progress.revokeCriteria(criteria);}catch(Exception ignored){}}}
    @EventHandler public void interact(PlayerInteractEvent e){World w=e.getPlayer().getWorld();if(isProtectedGriefSpawn(w)||!authed(e.getPlayer().getUniqueId())||(gameModes!=null&&gameModes.isLobby(w)&&!isCreator(e.getPlayer()))||e.getClickedBlock()!=null&&!getConfig().getBoolean("admin-worlds."+w.getName()+".interact",getConfig().getBoolean("admin-worlds.defaults.interact",true)))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void block(BlockPlaceEvent e){World w=e.getBlock().getWorld();if(isProtectedGriefSpawn(w)||!authed(e.getPlayer().getUniqueId())||(gameModes!=null&&gameModes.isLobby(w)&&!isCreator(e.getPlayer()))||!getConfig().getBoolean("admin-worlds."+w.getName()+".block-place",getConfig().getBoolean("admin-worlds.defaults.block-place",true)))e.setCancelled(true);}
    @EventHandler public void breakBlock(BlockBreakEvent e){World w=e.getBlock().getWorld();if(isProtectedGriefSpawn(w)||!authed(e.getPlayer().getUniqueId())||(gameModes!=null&&gameModes.isLobby(w)&&!isCreator(e.getPlayer()))||!getConfig().getBoolean("admin-worlds."+w.getName()+".block-break",getConfig().getBoolean("admin-worlds.defaults.block-break",true)))e.setCancelled(true);}
    @EventHandler public void inventory(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(!authed(p.getUniqueId())){e.setCancelled(true);return;}if(gameModes!=null&&gameModes.isLobby(p.getWorld())&&!isCreator(p)){e.setCancelled(true);return;}if(e.getView().getTitle().equals(GameModeCommand.MENU)||e.getView().getTitle().equals(GameModeCommand.INSTANCES))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void combatTag(EntityDamageByEntityEvent e){if(!(e.getEntity() instanceof Player victim)||e.getFinalDamage()<=0)return;Player attacker=null;Entity damager=e.getDamager();if(damager instanceof Player player)attacker=player;else if(damager instanceof Projectile projectile&&projectile.getShooter() instanceof Player player)attacker=player;if(attacker==null||attacker.equals(victim)||!pvpEnabled(attacker.getWorld())||!authed(attacker.getUniqueId())||!authed(victim.getUniqueId())||gameModes.isLobby(attacker.getWorld())||gameModes.isLobby(victim.getWorld())||!Objects.equals(gameModes.instanceOf(attacker.getWorld().getName()),gameModes.instanceOf(victim.getWorld().getName())))return;long now=System.currentTimeMillis();if(now-combatUntil.getOrDefault(attacker.getUniqueId(),0L)>30_000L)combatUntil.put(attacker.getUniqueId(),now);if(now-combatUntil.getOrDefault(victim.getUniqueId(),0L)>30_000L)combatUntil.put(victim.getUniqueId(),now);tagCombat(attacker,victim);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void syncPvpAfterWorldLoad(org.bukkit.event.world.WorldLoadEvent e){try{String scope=gameModes.instanceOf(e.getWorld().getName());if(scope!=null)e.getWorld().setPVP(db.pvpEnabled(scope)&&!gameModes.isSpawnWorld(e.getWorld()));}catch(Exception ex){getLogger().warning("Could not apply PvP setting in "+e.getWorld().getName()+": "+ex.getMessage());}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void pvpToggleDamage(EntityDamageByEntityEvent e){if(e.getEntity() instanceof Player spawnTarget&&isProtectedGriefSpawn(spawnTarget.getWorld())){e.setCancelled(true);return;}if(!(e.getEntity() instanceof Player)||!(e.getDamager() instanceof Player)&&!(e.getDamager() instanceof Projectile projectile&&projectile.getShooter() instanceof Player))return;Player target=(Player)e.getEntity();if(!pvpEnabled(target.getWorld()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.MONITOR) public void clearCombatOnDeath(PlayerDeathEvent e){UUID id=e.getEntity().getUniqueId();UUID opponent=combatOpponents.get(id);clearCombat(id);if(opponent!=null)clearCombat(opponent);Bukkit.getScheduler().runTaskLater(this,()->{clearCombat(id);if(opponent!=null)clearCombat(opponent);},1L);}
    @EventHandler(priority=EventPriority.MONITOR) public void damage(EntityDamageEvent e){if(e.getEntity() instanceof Player p){UUID id=p.getUniqueId();if(gameModes!=null&&gameModes.isLobby(p.getWorld())){e.setCancelled(true);if(e.getCause()==EntityDamageEvent.DamageCause.VOID){p.setInvulnerable(true);p.setHealth(p.getMaxHealth());p.teleport(gameModes.lobby().getSpawnLocation());}if(p.getHealth()<p.getMaxHealth())p.setHealth(p.getMaxHealth());p.setFireTicks(0);p.setFallDistance(0);return;}if(!authed(id)||afk(id)||van(id)||exemptDamage.contains(id)){e.setCancelled(true);}else if(e.getCause()==EntityDamageEvent.DamageCause.VOID&&p.getHealth()<=1.0){World lobby=gameModes==null?null:gameModes.lobby();if(lobby!=null){p.setInvulnerable(true);p.teleport(lobby.getSpawnLocation());p.setHealth(p.getMaxHealth());exemptDamage.add(id);Bukkit.getScheduler().runTaskLater(this,()->{if(p.isOnline()){exemptDamage.remove(id);refreshLobbyPlayer(p);}},40L);}}}}
    @EventHandler public void target(EntityTargetEvent e){if(e.getTarget() instanceof Player p&&(!authed(p.getUniqueId())||afk(p.getUniqueId())||van(p.getUniqueId())))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void cmd(PlayerCommandPreprocessEvent e){Player commandPlayer=e.getPlayer();String raw=e.getMessage().substring(1).split("\\s+",2)[0];if(raw.equalsIgnoreCase("portal")&&!authed(commandPlayer.getUniqueId())){e.setCancelled(true);commandPlayer.sendMessage("§cСначала войдите.");return;}if(raw.equalsIgnoreCase("van")||raw.equalsIgnoreCase("setrank")||raw.equalsIgnoreCase("world")){try{Rank rank=db.rank(commandPlayer.getUniqueId());if(!commandPlayer.isOp()&&(raw.equalsIgnoreCase("van")&&!rank.canUseVanish()||raw.equalsIgnoreCase("setrank")&&!rank.canSetRank()||raw.equalsIgnoreCase("world")&&!rank.canUseWorld())){e.setCancelled(true);commandPlayer.sendMessage("§cНедостаточно прав для этой команды.");return;}}catch(Exception ex){e.setCancelled(true);commandPlayer.sendMessage("§cНе удалось проверить ранг.");return;}}if(blockCombatEscape(commandPlayer,raw)){e.setCancelled(true);return;}String lower=e.getMessage().toLowerCase(Locale.ROOT);if(inCombat(commandPlayer.getUniqueId())&&(lower.equals("/l")||lower.startsWith("/l ")||lower.equals("/login")||lower.startsWith("/login "))){e.setCancelled(true);commandPlayer.sendMessage("§cВ бою нельзя перелогиниться и снять боевую метку.");return;}if(!authed(commandPlayer.getUniqueId())&&!e.getMessage().toLowerCase().startsWith("/reg")&&!e.getMessage().toLowerCase().startsWith("/register")&&!e.getMessage().toLowerCase().startsWith("/l ")&&!e.getMessage().toLowerCase().startsWith("/login ")){e.setCancelled(true);e.getPlayer().sendMessage("§cСначала зарегистрируйтесь или войдите.");}}
}
